tasks.solution:
from contextlib import contextmanager, ExitStack

@contextmanager
def tag(name):
    print(f"<{name}>")
    try:
        yield
    finally:
        print(f"</{name}>")

with ExitStack() as stack:
    for name in input().split():
        stack.enter_context(tag(name))
    print("текст")

