def parse(text: str) -> dict[str, int]:
    result: dict[str, int] = {}
    for part in text.split(","):
        key, value = part.split("=")
        result[key.strip()] = int(value)
    return result

for key, value in sorted(parse(input()).items()):
    print(key, value)
